package com.rpb.reservation.workforce.statutory.annual;

import static com.rpb.reservation.workforce.statutory.annual.AnnualWageDtos.*;
import static com.rpb.reservation.workforce.statutory.annual.AnnualWageCalculator.*;
import com.rpb.reservation.workforce.application.WorkforceJson;
import com.rpb.reservation.workforce.domain.WorkforceException;
import com.rpb.reservation.workforce.payroll.*;
import com.rpb.reservation.workforce.payroll.PayrollDtos.*;
import com.rpb.reservation.workforce.statutory.*;
import com.rpb.reservation.walkin.api.CurrentActor;
import java.math.*;
import java.time.*;
import java.util.*;
import java.security.*;
import java.nio.charset.StandardCharsets;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Read-only projections of frozen payroll and append-only external evidence. */
@Repository public class AnnualWageRepository {
 public static final String OPENING_PAYROLL_CONFLICT="ANNUAL_OPENING_PAYROLL_CONFLICT";
 private final JdbcTemplate jdbc;private final WorkforceJson json;private final Clock clock;
 public AnnualWageRepository(JdbcTemplate jdbc,WorkforceJson json,Clock clock){this.jdbc=jdbc;this.json=json;this.clock=clock;}
 public String hash(Object x){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.write(x).getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 public void commandLock(UUID id){jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"workforce.annual.command:"+id);}
 public void lock(UUID tenant,UUID company,UUID employee,int year){jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"workforce.annual:"+tenant+":"+company+":"+employee+":"+year);}
 public void subject(UUID tenant,UUID company,UUID employee,int year){jdbc.update("insert into workforce_statutory_year_subjects(tenant_id,company_id,employee_id,year) values(?,?,?,?) on conflict do nothing",tenant,company,employee,year);}
 public record Saved(long version,Write write){}
 public record Opening(long version,OpeningMonth fact){}
 /** External actual coverage is a source even when the proposed ordinary row contains no AW. */
 public Optional<Opening> opening(UUID tenant,UUID company,UUID employee,YearMonth month){var saved=saved(tenant,company,employee,month.getYear());return saved.write().months().stream().filter(f->f.month().equals(month.toString())).findFirst().map(f->new Opening(saved.version(),f));}
 public Saved saved(UUID tenant,UUID company,UUID employee,int year){return jdbc.query("select version,snapshot from workforce_statutory_year_revisions where tenant_id=? and company_id=? and employee_id=? and year=? order by version desc limit 1",(r,n)->new Saved(r.getLong(1),json.read(r.getString(2),Write.class)),tenant,company,employee,year).stream().findFirst().orElse(new Saved(0,new Write(null,0L,List.of(),"")));}
 public void save(CurrentActor actor,UUID company,UUID employee,int year,Write c){subject(actor.tenantId(),company,employee,year);jdbc.update("insert into workforce_statutory_year_revisions(tenant_id,company_id,employee_id,year,version,snapshot,created_by) values(?,?,?,?,?,?::jsonb,?)",actor.tenantId(),company,employee,year,c.expectedVersion()+1,json.write(c),actor.actorId());}
 public <T> Optional<T> replay(CurrentActor a,UUID store,UUID company,UUID employee,int year,UUID command,String kind,Object payload,Class<T> type){return jdbc.query("select tenant_id,company_id,employee_id,year,store_id,actor_id,kind,payload,response from workforce_statutory_year_commands where id=?",(r,n)->{if(!a.tenantId().equals(r.getObject(1,UUID.class))||!company.equals(r.getObject(2,UUID.class))||!employee.equals(r.getObject(3,UUID.class))||year!=r.getInt(4)||!store.equals(r.getObject(5,UUID.class))||!a.actorId().equals(r.getObject(6,UUID.class))||!kind.equals(r.getString(7))||!json.read(r.getString(8),payload.getClass()).equals(payload))throw WorkforceException.conflict();return json.read(r.getString(9),type);},command).stream().findFirst();}
 public void command(CurrentActor a,UUID store,UUID company,UUID employee,int year,UUID id,String kind,Object c,Object response){subject(a.tenantId(),company,employee,year);jdbc.update("insert into workforce_statutory_year_commands(id,tenant_id,company_id,employee_id,year,store_id,actor_id,kind,payload,response) values(?,?,?,?,?,?,?,?,?::jsonb,?::jsonb)",id,a.tenantId(),company,employee,year,store,a.actorId(),kind,json.write(c),json.write(response));}
 public void reconciliation(UUID tenant,Reconciliation r){subject(tenant,r.companyId(),r.employeeId(),r.year());jdbc.update("insert into workforce_aw_reconciliations(id,tenant_id,company_id,employee_id,year,source_fingerprint,settlement_month,snapshot) values(?,?,?,?,?,?,?,?::jsonb)",r.id(),tenant,r.companyId(),r.employeeId(),r.year(),r.assessment().fingerprint(),YearMonth.parse(r.settlementMonth()).atDay(1),json.write(r));}
 public List<Reconciliation> reconciliations(UUID tenant,UUID company,UUID employee,int year){return jdbc.query("select snapshot from workforce_aw_reconciliations where tenant_id=? and company_id=? and employee_id=? and year=? order by created_at,id",(r,n)->json.read(r.getString(1),Reconciliation.class),tenant,company,employee,year);}
 public boolean internal(UUID tenant,UUID company,UUID employee,YearMonth month){return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from workforce_pay_approved_months where tenant_id=? and company_id=? and employee_id=? and period_month=?) or exists(select 1 from workforce_pay_batches b cross join lateral jsonb_array_elements(b.calculation->'lines') l where b.tenant_id=? and b.company_id=? and b.period_month=? and b.status in ('confirmed','published') and l->>'employeeId'=?)",Boolean.class,tenant,company,employee,month.atDay(1),tenant,company,month.atDay(1),employee.toString()))||new com.rpb.reservation.workforce.payroll.segment.SegmentRepository(jdbc,json).latest(tenant,company,employee,month).isPresent();}
 public Context capture(UUID tenant,UUID company,UUID employee,int year){return new AnnualWageSources(jdbc,json,clock,this).capture(tenant,company,employee,year);}
 public Context captureForPayroll(UUID tenant,UUID company,UUID employee,YearMonth month){return new AnnualWageSources(jdbc,json,clock,this).captureForPayroll(tenant,company,employee,month);}
 public Context captureForPayrollAssuming(UUID tenant,UUID company,UUID employee,YearMonth month,PayrollSources.Assumptions assumptions){return new AnnualWageSources(jdbc,json,clock,this).captureForPayrollAssuming(tenant,company,employee,month,assumptions);}
 public static List<WageEvent> events(LineInput input,String source){return input.items().stream().filter(i->i.eventEvidence()!=null).map(i->new WageEvent(i.eventEvidence(),i.amount(),source)).toList();}
 public static BigDecimal aw(List<WageEvent> events){return events.stream().filter(e->e.evidence().classification().equals("AW")).map(e->amount(e.amount())).reduce(BigDecimal.ZERO,BigDecimal::add);}
 public static MonthFact fact(YearMonth month,String state,BigDecimal ow,StatutoryDtos.CpfProfile cpf,StatutoryPolicies.Policy policy,String ee,String er,String source,List<WageEvent> events,List<String> issues){String capped=ow!=null&&ow.signum()==0&&state.equals("known-zero")?"0.00":ow==null||policy==null?null:money(cpf!=null&&"foreign".equals(cpf.citizenship())?BigDecimal.ZERO:ow.min(StatutoryPolicyConfig.number(policy.config().owCeiling())));return new MonthFact(month.toString(),state,money(ow),capped,cpf,policy,ee,er,source,List.copyOf(events),issues);}
 public static Context current(Context c,YearMonth month,BigDecimal ow,StatutoryDtos.CpfProfile cpf,StatutoryPolicies.Policy policy,List<WageEvent> events){var facts=new ArrayList<MonthFact>();for(var f:c.months())facts.add(f.month().equals(month.toString())?fact(month,"actual",ow,cpf,policy,"0.00","0.00","current-payroll",events,List.of()):f);return new Context(c.companyId(),c.employeeId(),c.year(),c.version(),c.fingerprint(),List.copyOf(facts),c.issues(),c.writable());}
 public void registerOpening(UUID tenant,UUID company,UUID employee,int year,List<OpeningMonth> months){
  subject(tenant,company,employee,year);for(var pair:months.stream().flatMap(m->m.events().stream().map(e->Map.entry(m,e))).sorted(Comparator.comparing(p->p.getValue().evidence().eventId())).toList()){var month=pair.getKey();var event=pair.getValue();
   var id=event.evidence().eventId();jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"workforce.wage.event:"+tenant+":"+company+":"+id);
   var old=jdbc.query("select snapshot,employee_id from workforce_wage_events where tenant_id=? and company_id=? and event_id=?",(r,n)->{var saved=json.read(r.getString(1),WageEvent.class);if(!employee.equals(r.getObject(2,UUID.class))||!saved.evidence().equals(event.evidence())||amount(saved.amount()).compareTo(amount(event.amount()))!=0||!saved.source().startsWith("opening:"))throw new WorkforceException("WAGE_EVENT_ALREADY_CONSUMED",409);return saved;},tenant,company,id);
   if(old.isEmpty())jdbc.update("insert into workforce_wage_events(tenant_id,company_id,event_id,employee_id,year,snapshot) values(?,?,?,?,?,?::jsonb)",tenant,company,id,employee,year,json.write(new WageEvent(event.evidence(),event.amount(),"opening:"+month.evidenceReference())));
  }
 }
 public void freeze(PayrollRepository.State batch,PayrollSources.Capture capture){for(var source:capture.lines())if(source.annual()!=null){var line=batch.calculation().lines().stream().filter(l->l.employeeId().equals(source.employee().id())).findFirst().orElseThrow();var eventList=events(line.input(),"batch:"+batch.id());var context=current(source.annual(),batch.month(),amount(line.grossPay()).subtract(aw(eventList)),line.profile().cpf(),capture.statutoryPolicy(),eventList);var frozen=new FrozenAssessment(batch.id(),line.employeeId(),batch.calculation().sourceFingerprint(),context,new AnnualWageCalculator().assess(context));subject(batch.tenant(),batch.company(),line.employeeId(),batch.month().getYear());jdbc.update("insert into workforce_aw_assessments(tenant_id,company_id,employee_id,year,batch_id,source_fingerprint,snapshot) values(?,?,?,?,?,?,?::jsonb)",batch.tenant(),batch.company(),line.employeeId(),batch.month().getYear(),batch.id(),frozen.sourceFingerprint(),json.write(frozen));}}
 public List<FrozenAssessment> assessments(UUID tenant,UUID company,UUID employee,int year){return jdbc.query("select snapshot from workforce_aw_assessments where tenant_id=? and company_id=? and employee_id=? and year=? order by created_at,batch_id",(r,n)->json.read(r.getString(1),FrozenAssessment.class),tenant,company,employee,year);}
 public void consume(PayrollRepository.State batch){for(var line:batch.calculation().lines())for(var event:events(line.input(),"batch:"+batch.id())){
  var id=event.evidence().eventId();lock(batch.tenant(),batch.company(),line.employeeId(),YearMonth.parse(event.evidence().contributionMonth()).getYear());subject(batch.tenant(),batch.company(),line.employeeId(),YearMonth.parse(event.evidence().contributionMonth()).getYear());
  var old=jdbc.query("select snapshot,employee_id from workforce_wage_events where tenant_id=? and company_id=? and event_id=?",(r,n)->{var e=json.read(r.getString(1),WageEvent.class);if(e.source().startsWith("opening:")||!line.employeeId().equals(r.getObject(2,UUID.class))||!e.evidence().equals(event.evidence())||amount(e.amount()).compareTo(amount(event.amount()))!=0)throw new WorkforceException("WAGE_EVENT_ALREADY_CONSUMED",409);return e;},batch.tenant(),batch.company(),id);
  if(old.isEmpty())jdbc.update("insert into workforce_wage_events(tenant_id,company_id,event_id,employee_id,year,snapshot) values(?,?,?,?,?,?::jsonb)",batch.tenant(),batch.company(),id,line.employeeId(),YearMonth.parse(event.evidence().contributionMonth()).getYear(),json.write(event));
  if(Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from workforce_wage_event_consumptions where tenant_id=? and company_id=? and event_id=? and active and batch_id is distinct from ?)",Boolean.class,batch.tenant(),batch.company(),id,batch.id())))throw new WorkforceException("WAGE_EVENT_ALREADY_CONSUMED",409);
  jdbc.update("insert into workforce_wage_event_consumptions(tenant_id,company_id,employee_id,event_id,batch_id) values(?,?,?,?,?) on conflict do nothing",batch.tenant(),batch.company(),line.employeeId(),id,batch.id());
 }}
 public void release(UUID tenant,UUID batch){jdbc.update("update workforce_wage_event_consumptions set active=false,released_at=now() where tenant_id=? and batch_id=? and active",tenant,batch);}
}
